1	import { isRenderThrottlingEnabled } from "../reactUtils";
2	
3	export type Animation<R extends object> = (params: {
4	  deltaTime: number;
5	  state?: R;
6	}) => R | null | undefined;
7	
8	export class AnimationController {
9	  private static isRunning = false;
10	  private static animations = new Map<
11	    string,
12	    {
13	      animation: Animation<any>;
14	      lastTime: number;
15	      state: any;
16	    }
17	  >();
18	
19	  static start<R extends object>(key: string, animation: Animation<R>) {
20	    const initialState = animation({
21	      deltaTime: 0,
22	      state: undefined,
23	    });
24	
25	    if (initialState) {
26	      AnimationController.animations.set(key, {
27	        animation,
28	        lastTime: 0,
29	        state: initialState,
30	      });
31	
32	      if (!AnimationController.isRunning) {
33	        AnimationController.isRunning = true;
34	
35	        if (isRenderThrottlingEnabled()) {
36	          requestAnimationFrame(AnimationController.tick);
37	        } else {
38	          setTimeout(AnimationController.tick, 0);
39	        }
40	      }
41	    }
42	  }
43	
44	  private static tick() {
45	    if (AnimationController.animations.size > 0) {
46	      for (const [key, animation] of AnimationController.animations) {
47	        const now = performance.now();
48	        const deltaTime =
49	          animation.lastTime === 0 ? 0 : now - animation.lastTime;
50	
51	        const state = animation.animation({
52	          deltaTime,
53	          state: animation.state,
54	        });
55	
56	        if (!state) {
57	          AnimationController.animations.delete(key);
58	
59	          if (AnimationController.animations.size === 0) {
60	            AnimationController.isRunning = false;
61	            return;
62	          }
63	        } else {
64	          animation.lastTime = now;
65	          animation.state = state;
66	        }
67	      }
68	
69	      if (isRenderThrottlingEnabled()) {
70	        requestAnimationFrame(AnimationController.tick);
71	      } else {
72	        setTimeout(AnimationController.tick, 0);
73	      }
74	    }
75	  }
76	
77	  static running(key: string) {
78	    return AnimationController.animations.has(key);
79	  }
80	
81	  static cancel(key: string) {
82	    AnimationController.animations.delete(key);
83	  }
84	}
