9	import type { LaserPointerOptions } from "@excalidraw/laser-pointer";
10	
11	import type { AnimationFrameHandler } from "./animation-frame-handler";
12	import type App from "./components/App";
13	import type { AppState } from "./types";
14	
15	export interface Trail {
16	  start(container: SVGSVGElement): void;
17	  stop(): void;
18	
19	  startPath(x: number, y: number): void;
20	  addPointToPath(x: number, y: number): void;
21	  endPath(): void;
22	}
23	
24	export interface AnimatedTrailOptions {
25	  fill: (trail: AnimatedTrail) => string;
26	  stroke?: (trail: AnimatedTrail) => string;
27	  animateTrail?: boolean;
28	}
29	
30	export class AnimatedTrail implements Trail {
31	  private currentTrail?: LaserPointer;
32	  private pastTrails: LaserPointer[] = [];
33	
34	  private container?: SVGSVGElement;
35	  private trailElement: SVGPathElement;
36	  private trailAnimation?: SVGAnimateElement;
37	
38	  constructor(
39	    private animationFrameHandler: AnimationFrameHandler,
40	    protected app: App,
41	    private options: Partial<LaserPointerOptions> &
42	      Partial<AnimatedTrailOptions>,
43	  ) {
44	    this.animationFrameHandler.register(this, this.onFrame.bind(this));
45	
46	    this.trailElement = document.createElementNS(SVG_NS, "path");
47	    if (this.options.animateTrail) {
48	      this.trailAnimation = document.createElementNS(SVG_NS, "animate");
49	      // TODO: make this configurable
50	      this.trailAnimation.setAttribute("attributeName", "stroke-dashoffset");
51	      this.trailElement.setAttribute("stroke-dasharray", "7 7");
52	      this.trailElement.setAttribute("stroke-dashoffset", "10");
53	      this.trailAnimation.setAttribute("from", "0");
54	      this.trailAnimation.setAttribute("to", `-14`);
55	      this.trailAnimation.setAttribute("dur", "0.3s");
56	      this.trailElement.appendChild(this.trailAnimation);
57	    }
58	  }
59	
60	  get hasCurrentTrail() {
61	    return !!this.currentTrail;
62	  }
63	
64	  hasLastPoint(x: number, y: number) {
65	    if (this.currentTrail) {
66	      const len = this.currentTrail.originalPoints.length;
67	      return (
68	        this.currentTrail.originalPoints[len - 1][0] === x &&
69	        this.currentTrail.originalPoints[len - 1][1] === y
70	      );
71	    }
72	
73	    return false;
74	  }
75	
76	  start(container?: SVGSVGElement) {
77	    if (container) {
78	      this.container = container;
79	    }
80	
81	    if (this.trailElement.parentNode !== this.container && this.container) {
82	      this.container.appendChild(this.trailElement);
83	    }
84	
85	    this.animationFrameHandler.start(this);
86	  }
87	
88	  stop() {
89	    this.animationFrameHandler.stop(this);
90	
91	    if (this.trailElement.parentNode === this.container) {
92	      this.container?.removeChild(this.trailElement);
93	    }
94	  }
95	
96	  startPath(x: number, y: number) {
97	    this.currentTrail = new LaserPointer(this.options);
98	
99	    this.currentTrail.addPoint([x, y, performance.now()]);
100	
101	    this.update();
102	  }
103	
104	  addPointToPath(x: number, y: number) {
105	    if (this.currentTrail) {
106	      this.currentTrail.addPoint([x, y, performance.now()]);
107	      this.update();
108	    }
109	  }
110	
111	  endPath() {
112	    if (this.currentTrail) {
113	      this.currentTrail.close();
114	      this.currentTrail.options.keepHead = false;
115	      this.pastTrails.push(this.currentTrail);
116	      this.currentTrail = undefined;
117	      this.update();
118	    }
119	  }
120	
121	  getCurrentTrail() {
122	    return this.currentTrail;
123	  }
124	
125	  clearTrails() {
126	    this.pastTrails = [];
127	    this.currentTrail = undefined;
128	    this.update();
129	  }
130	
131	  private update() {
132	    this.start();
133	    if (this.trailAnimation) {
134	      this.trailAnimation.setAttribute("begin", "indefinite");
135	      this.trailAnimation.setAttribute("repeatCount", "indefinite");
136	    }
137	  }
138	
139	  private onFrame() {
140	    const paths: string[] = [];
141	
142	    for (const trail of this.pastTrails) {
143	      paths.push(this.drawTrail(trail, this.app.state));
144	    }
145	
146	    if (this.currentTrail) {
147	      const currentPath = this.drawTrail(this.currentTrail, this.app.state);
148	
149	      paths.push(currentPath);
150	    }
151	
152	    this.pastTrails = this.pastTrails.filter((trail) => {
153	      return trail.getStrokeOutline().length !== 0;
154	    });
155	
156	    if (paths.length === 0) {
157	      this.stop();
158	    }
159	
160	    const svgPaths = paths.join(" ").trim();
161	
162	    this.trailElement.setAttribute("d", svgPaths);
163	    if (this.trailAnimation) {
164	      this.trailElement.setAttribute(
165	        "fill",
166	        (this.options.fill ?? (() => "black"))(this),
167	      );
168	      this.trailElement.setAttribute(
169	        "stroke",
170	        (this.options.stroke ?? (() => "black"))(this),
171	      );
172	    } else {
173	      this.trailElement.setAttribute(
174	        "fill",
175	        (this.options.fill ?? (() => "black"))(this),
176	      );
177	    }
178	  }
179	
180	  private drawTrail(trail: LaserPointer, state: AppState): string {
181	    const _stroke = trail
182	      .getStrokeOutline(trail.options.size / state.zoom.value)
183	      .map(([x, y]) => {
184	        const result = sceneCoordsToViewportCoords(
185	          { sceneX: x, sceneY: y },
186	          state,
187	        );
188	
189	        return [result.x, result.y];
190	      });
191	
192	    const stroke = this.trailAnimation
193	      ? _stroke.slice(0, _stroke.length / 2)
194	      : _stroke;
195	
196	    return getSvgPathFromStroke(stroke, true);
197	  }
198	}
